pub fn runtime_boxed_abi(symbol: &str, arity: usize) -> Option<&'static RuntimeBoxedAbi> {
    let index = RUNTIME_BOXED_ABIS
        .binary_search_by_key(&symbol, |abi| abi.symbol)
        .ok()?;
    let abi = &RUNTIME_BOXED_ABIS[index];
    (abi.arity == arity).then_some(abi)
}

/// Explicitly admitted positional op calls; every target consumes this mapping.
pub const RUNTIME_BOXED_OP_KINDS: &[crate::OpKind] = &[
    crate::OpKind::BytearrayCount,
    crate::OpKind::BytearrayCountSlice,
    crate::OpKind::BytearrayEndswith,
    crate::OpKind::BytearrayEndswithSlice,
    crate::OpKind::BytearrayFind,
    crate::OpKind::BytearrayFindSlice,
    crate::OpKind::BytearrayStartswith,
    crate::OpKind::BytearrayStartswithSlice,
    crate::OpKind::BytesCount,
    crate::OpKind::BytesCountSlice,
    crate::OpKind::BytesEndswith,
    crate::OpKind::BytesEndswithSlice,
    crate::OpKind::BytesFind,
    crate::OpKind::BytesFindSlice,
    crate::OpKind::BytesStartswith,
    crate::OpKind::BytesStartswithSlice,
    crate::OpKind::StringCount,
    crate::OpKind::StringCountSlice,
    crate::OpKind::StringEndswith,
    crate::OpKind::StringEndswithSlice,
    crate::OpKind::StringFind,
    crate::OpKind::StringFindSlice,
    crate::OpKind::StringStartswith,
    crate::OpKind::StringStartswithSlice,
];

pub fn runtime_boxed_op_abi(kind: crate::OpKind) -> Option<&'static RuntimeBoxedAbi> {
    match kind {
        crate::OpKind::BytearrayCount => Some(&RUNTIME_BOXED_ABIS[221]),
        crate::OpKind::BytearrayCountSlice => Some(&RUNTIME_BOXED_ABIS[222]),
        crate::OpKind::BytearrayEndswith => Some(&RUNTIME_BOXED_ABIS[223]),
        crate::OpKind::BytearrayEndswithSlice => Some(&RUNTIME_BOXED_ABIS[224]),
        crate::OpKind::BytearrayFind => Some(&RUNTIME_BOXED_ABIS[226]),
        crate::OpKind::BytearrayFindSlice => Some(&RUNTIME_BOXED_ABIS[227]),
        crate::OpKind::BytearrayStartswith => Some(&RUNTIME_BOXED_ABIS[233]),
        crate::OpKind::BytearrayStartswithSlice => Some(&RUNTIME_BOXED_ABIS[234]),
        crate::OpKind::BytesCount => Some(&RUNTIME_BOXED_ABIS[235]),
        crate::OpKind::BytesCountSlice => Some(&RUNTIME_BOXED_ABIS[236]),
        crate::OpKind::BytesEndswith => Some(&RUNTIME_BOXED_ABIS[237]),
        crate::OpKind::BytesEndswithSlice => Some(&RUNTIME_BOXED_ABIS[238]),
        crate::OpKind::BytesFind => Some(&RUNTIME_BOXED_ABIS[239]),
        crate::OpKind::BytesFindSlice => Some(&RUNTIME_BOXED_ABIS[240]),
        crate::OpKind::BytesStartswith => Some(&RUNTIME_BOXED_ABIS[246]),
        crate::OpKind::BytesStartswithSlice => Some(&RUNTIME_BOXED_ABIS[247]),
        crate::OpKind::StringCount => Some(&RUNTIME_BOXED_ABIS[2192]),
        crate::OpKind::StringCountSlice => Some(&RUNTIME_BOXED_ABIS[2193]),
        crate::OpKind::StringEndswith => Some(&RUNTIME_BOXED_ABIS[2194]),
        crate::OpKind::StringEndswithSlice => Some(&RUNTIME_BOXED_ABIS[2195]),
        crate::OpKind::StringFind => Some(&RUNTIME_BOXED_ABIS[2197]),
        crate::OpKind::StringFindSlice => Some(&RUNTIME_BOXED_ABIS[2198]),
        crate::OpKind::StringStartswith => Some(&RUNTIME_BOXED_ABIS[2220]),
        crate::OpKind::StringStartswithSlice => Some(&RUNTIME_BOXED_ABIS[2221]),
        _ => None,
    }
}
